words = {e["word"]: e for e in json.load(open("src/db/content/vocabulary/oxford-3000.json"))}
out, unknown, multi = {}, [], {}
for theme, text in THEMES.items():
    for w in text.split():
        w = w.lower()
        if w not in words: unknown.append(w); continue
        if w in out and out[w] != theme: multi.setdefault(w, [out[w]]).append(theme); continue
        out[w] = theme
print("themed:", len(out), "of", len(words), "| unknown:", len(set(unknown)), "| in several themes (first kept):", len(multi))
print("unknown sample:", sorted(set(unknown))[:30])
json.dump(dict(sorted(out.items())), open("src/db/content/vocabulary/themes.json", "w"), ensure_ascii=False, indent=1)
from collections import Counter
print(Counter(out.values()))
